// Edit only these non-secret values. Use one dedicated test ticket per request.
const config = {
  threshold_url: 'https://simultaneously-decided-links-griffin.trycloudflare.com/api/v1/webhooks/ugO_EODO88DejY350GK9312jm3nDDU2B',
  portal_id: '247531757',
  ticket_id: '337799898846',
  text: 'Refund order #ORD-1002 for $65.00',
  sender: 'ana.bootcamp@example.com'
};
if (!/^https:\/\//.test(config.threshold_url)) throw new Error('Configure an HTTPS Threshold URL reachable from n8n Cloud');
for (const key of ['portal_id','ticket_id']) if (!/^[0-9]{1,32}$/.test(config[key])) throw new Error('Configure ' + key);
const event_id = 'hubspot:' + config.portal_id + ':ticket:' + config.ticket_id;
const payload = {text: config.text, sender: config.sender, external_id: event_id,
  crm: {provider:'hubspot', portal_id:config.portal_id, ticket_id:config.ticket_id}};
const raw_body = JSON.stringify(payload);
const timestamp = String(Math.floor(Date.now()/1000));
return [{json: {url:config.threshold_url, event_id, raw_body, timestamp,
  signed_text:timestamp + '.' + raw_body}}];

const statusCode = Number($json.statusCode);
let body = $json.body;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error('Threshold returned a body that is not valid JSON.');
  }
}

if (statusCode !== 202 || body?.accepted !== true) {
  throw new Error(
    'Unexpected Threshold response: ' +
    JSON.stringify({
      statusCode: $json.statusCode,
      body_type: typeof $json.body,
      body: $json.body ?? null,
      response_keys: Object.keys($json)
    })
  );
}

return [{
  json: {
    accepted: true,
    duplicate: body.duplicate,
    event_id: body.event_id,
    message: 'Accepted for processing; completion must be verified separately.'
  }
}];
